#!/bin/bash
# edit-rulebook.sh -- GENERATED by effortless-rulebook-editor.
#
# Dockerfile and its sibling files (container-entrypoint.sh, boot-server.js,
# effortless.editor.json) live at docker/Dockerfile relative to THIS script's
# own folder.
#
# Ports are fixed, always: 42441 (API), 42442 (UI), 5442 (Postgres).
#
# Refresh your browser after editing effortless-rulebook.json -- the container's
# filesystem watcher detects the change, re-runs `effortless build`, and
# restarts the API + UI automatically.

set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

DOCKERFILE_PATH="docker/Dockerfile"
EXTERNAL_SRC_MOUNTED=
EXTERNAL_SRC_HOST_PATH=""

# On Windows Git Bash (MSYS), MSYS silently rewrites POSIX-looking paths in
# command arguments before docker.exe ever sees them. Applied blindly to a
# `docker run -v SRC:DST` argument, it mangles the CONTAINER-side path too
# (observed in practice: "/app/effortless-rulebook" became
# "\Program Files\Git\app\effortless-rulebook"), so the rulebook folder never
# actually appears inside the container at all. Disabling MSYS's path
# conversion for the docker commands below and converting the HOST-side path
# ourselves (native Windows path via cygpath) fixes this without affecting
# macOS/Linux, where none of this applies (MSYSTEM is unset there).
if [ -n "${MSYSTEM:-}" ] && command -v cygpath >/dev/null 2>&1; then
  export MSYS_NO_PATHCONV=1
  to_native_path() { cygpath -w "$1"; }
else
  to_native_path() { printf '%s' "$1"; }
fi

IMAGE_NAME="effortless-rulebook-editor"
CONTAINER_NAME="effortless-rulebook-editor"
API_PORT=42441
UI_PORT=42442
PG_PORT=5442

# Stop our own previous container, AND whatever else is squatting on these
# three ports (e.g. an old/differently-named instance from before this
# project pinned its own ports below). These ports are only ever used by
# short-lived, disposable rulebook-editor instances, so taking one over is
# safe and intentional -- unlike quietly landing on a random port and
# leaving a stale container running the OLD build underneath a live editing
# session.
for PORT in "$API_PORT" "$UI_PORT" "$PG_PORT"; do
  STALE_CIDS=$(docker ps -q --filter "publish=$PORT")
  [ -n "$STALE_CIDS" ] && docker rm -f $STALE_CIDS >/dev/null 2>&1 || true
done
docker rm -f "$CONTAINER_NAME" >/dev/null 2>&1 || true

# Build only if the image doesn't exist yet. Run ./edit-rulebook.sh --rebuild
# to force a fresh image build (e.g. after pulling a new Dockerfile).
DOCKERFILE_DIR="$(dirname "$DOCKERFILE_PATH")"
if [ "${1:-}" = "--rebuild" ] || ! docker image inspect "$IMAGE_NAME" >/dev/null 2>&1; then
  echo "Building $IMAGE_NAME image..."
  docker build -t "$IMAGE_NAME" -f "$DOCKERFILE_PATH" "$DOCKERFILE_DIR"
fi

RULEBOOK_DIR_NATIVE="$(to_native_path "$(pwd)")"
SSOTME_DIR_NATIVE="$(to_native_path "$HOME/.ssotme")"

DOCKER_RUN_ARGS=(
  -d
  --name "$CONTAINER_NAME"
  -p "$API_PORT:5177"
  -p "$UI_PORT:5174"
  -p "$PG_PORT:5432"
  -v "$RULEBOOK_DIR_NATIVE:/app/effortless-rulebook"
  -v "$SSOTME_DIR_NATIVE:/root/.ssotme-ro:ro"
)

# Second bind-mount: only when -p pathToExternalSrc=... was passed at
# generation time. Otherwise the container keeps ALL of its scratch/
# generated-code state purely internal (see container-entrypoint.sh's
# effortless-root symlink target) -- nothing lands on the host, nothing
# needs a .gitignore entry.
if [ -n "$EXTERNAL_SRC_MOUNTED" ]; then
  mkdir -p "$EXTERNAL_SRC_HOST_PATH"
  # .gitignore the whole external-src folder -- it's disposable container
  # scratch state (effortless.json + every generated file), not something
  # to commit.
  if [ ! -f "$EXTERNAL_SRC_HOST_PATH/.gitignore" ]; then
    printf '*\n' > "$EXTERNAL_SRC_HOST_PATH/.gitignore"
  fi
  EXTERNAL_SRC_NATIVE="$(to_native_path "$(cd "$EXTERNAL_SRC_HOST_PATH" && pwd)")"
  DOCKER_RUN_ARGS+=( -v "$EXTERNAL_SRC_NATIVE:/app/effortless-editor-tmp" )
  DOCKER_RUN_ARGS+=( -e "EFFORTLESS_EDITOR_TEMPDIR_MOUNTED=1" )
fi

# Forward the host's Anthropic key into the container so the generated API's
# chat endpoint (POST /api/chat, see chatbot.js) can reach Claude.
#
# Two sources, in order: an `effortless.env` file next to this script, then the
# invoking shell's environment. The file is checked FIRST and matters most --
# relying on the shell alone is fragile, because this script is commonly run
# from an IDE terminal, a GUI launcher, or a non-login shell that never sourced
# ~/.zshrc, and the key then silently is not forwarded (the container starts
# fine and only the chat reports itself unavailable, which is a confusing way
# to discover a missing env var). `effortless.env` is already gitignored by the
# standard effortless .gitignore, so the secret stays out of version control.
#
# The value is passed to docker by NAME (`-e VAR`, no `=value`), so it is never
# written into this script, the image, or any generated file.
ENV_FILE="$(dirname "$0")/effortless.env"
if [ -f "$ENV_FILE" ]; then
  # `set -a` marks everything defined while it is on for export, so a plain
  # `ANTHROPIC_API_KEY=sk-...` line in the file (no `export` keyword needed)
  # still reaches the docker process.
  set -a
  # shellcheck disable=SC1090
  . "$ENV_FILE"
  set +a
fi

if [ -n "${ANTHROPIC_API_KEY:-}" ]; then
  DOCKER_RUN_ARGS+=( -e ANTHROPIC_API_KEY )
else
  echo "NOTE: ANTHROPIC_API_KEY is not set, so the admin portal's chat widget"
  echo "      will report itself unavailable. Everything else runs normally."
  echo "      To enable it, create $ENV_FILE containing:"
  echo "          ANTHROPIC_API_KEY=sk-ant-..."
  echo "      (that filename is already gitignored), or export the variable"
  echo "      in the shell you run this script from."
fi

echo "Starting $CONTAINER_NAME container on fixed ports ($API_PORT, $UI_PORT, $PG_PORT)..."
docker run "${DOCKER_RUN_ARGS[@]}" "$IMAGE_NAME"

echo ""
echo "effortless-rulebook-editor is starting up."
echo "  API:  http://localhost:$API_PORT/api/state"
echo "  DOCS: http://localhost:$API_PORT/api/docs"
echo "                            (START HERE to build an app against this API: every"
echo "                            route, the read-snake_case/write-PascalCase rule, and"
echo "                            pointers to /api/rulespeak + /api/source. Derived from"
echo "                            the live route table, so it cannot go stale.)"
echo "  UI:   http://localhost:$UI_PORT   (shows a live boot/progress page immediately --"
echo "                            no need to wait before opening it; it hands off"
echo "                            to the real app automatically once ready, and has"
echo "                            its own Rebuild button + log view at any time)"
echo "  PG:   postgresql://postgres:postgres@localhost:$PG_PORT/effortless-rulebook"
echo "                            (for a host psql client / GUI tool -- this is the"
echo "                            ONLY supported way to inspect data directly; the"
echo "                            DB is reseeded from the rulebook on every rebuild)"
echo ""
echo "Edit effortless-rulebook.json to trigger a rebuild -- the container watches"
echo "the file (and the UI's Rebuild button) and rebuilds automatically."
echo ""
echo "Following container logs now (Ctrl-C stops watching logs -- the container keeps running;"
echo "re-run this script, or 'docker logs -f $CONTAINER_NAME', to watch again)..."
echo ""
exec docker logs -f "$CONTAINER_NAME"
